def extract_connected_component(grid, start_r, start_c, target_color):
    """Extract a connected component starting from position"""
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    visited = set()
    queue = [(start_r, start_c)]
    comp = []

    while queue:
        r, c = queue.pop(0)
        if (r, c) in visited or r < 0 or r >= rows or c < 0 or c >= cols or grid[r][c] != target_color:
            continue
        visited.add((r, c))
        comp.append((r, c))

        # Check neighbors
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if (nr, nc) not in visited and 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == target_color:
                queue.append((nr, nc))

    return sorted(comp)

